assert hashlib.sha256(P104_CODE).hexdigest() == P104_SHA, 'P104_REFERENCE_CORRUPTED'

CAMERA_APPEND = r'''

# == P105 CAMERA-ONLY OBSERVER (APPENDED; ORIGINAL CLASS UNCHANGED) ==
# Read-only physics access; no calls to stepSimulation, robot control, or AI.
_Stage105OriginalRecorder = Stage62Recorder
class Stage105CameraOnlyRecorder(_Stage105OriginalRecorder):
    def __init__(self,p,out,fps=20,w=1920,h=1080):
        super().__init__(p,out,fps=fps,w=w,h=h)
        import json
        self._p105_path=Path(out).parent/'p105_views'
        self._p105_path.mkdir(exist_ok=False)
        self._p105_writers={
            'grip':imageio.get_writer(str(self._p105_path/'p105_grip_live.mp4'),fps=fps,codec='libx264',quality=7,macro_block_size=1),
            'follow':imageio.get_writer(str(self._p105_path/'p105_slider_follow_live.mp4'),fps=fps,codec='libx264',quality=7,macro_block_size=1)
        }
        self._p105_robot=None
        self._p105_palm_joint=None
        self._p105_xpoints=[]
        self._p105_errors=[]
        self._p105_no_track=0
        self._p105_frame_count={'grip':0,'follow':0}

    def _p105_find_palm(self):
        if self._p105_robot is not None:return
        p=self.p
        for i in range(p.getNumBodies()):
            b=p.getBodyUniqueId(i)
            for j in range(p.getNumJoints(b)):
                try:
                    joint_name=p.getJointInfo(b,j)[1].decode('utf-8','replace')
                    if joint_name=='palm_camera_fixed':
                        self._p105_robot=b;self._p105_palm_joint=j;return
                except Exception:continue

    def _p105_render(self,eye,target,fov):
        import numpy as np
        p=self.p;w,h=960,540
        view=p.computeViewMatrix(cameraEyePosition=eye,cameraTargetPosition=target,
                                 cameraUpVector=[0.,0.,1.])
        proj=p.computeProjectionMatrixFOV(fov=fov,aspect=w/h,nearVal=.015,farVal=5.)
        _,_,rgba,_,_=p.getCameraImage(w,h,viewMatrix=view,projectionMatrix=proj,
                                     renderer=p.ER_TINY_RENDERER)
        return np.asarray(rgba,dtype=np.uint8).reshape(h,w,4)[:,:,:3].copy()

    def frame(self,phase,force=False):
        prior=self.count
        super().frame(phase,force)
        if self.count==prior:return
        import numpy as np
        from PIL import Image,ImageDraw
        self._p105_find_palm()
        tracking=self._p105_robot is not None
        if tracking:
            try:
                xyz=self.p.getLinkState(self._p105_robot,self._p105_palm_joint,
                                       computeForwardKinematics=True)[0]
                x,y,z=[float(v) for v in xyz]
            except Exception as e:
                self._p105_errors.append({'frame':self.count,'error':repr(e)})
                tracking=False
        if not tracking:
            self._p105_no_track+=1
            x,y,z=0.,0.,1.18
        self._p105_xpoints.append({'frame':self.count,'x':x,'y':y,'z':z,'tracking':tracking})
        # Real world-space camera moves horizontally as the palm link travels.
        # It does not crop or pan a previously recorded image.
        eye_follow=[x+.38,-1.34,1.80]
        aim_follow=[x,0.,.91]
        # Near-grip observer travels with the physical palm, including vertical motion.
        eye_grip=[x+.34,y-.52,z+.16]
        aim_grip=[x,y,z-.18]
        for name,eye,aim,fov in (
            ('follow',eye_follow,aim_follow,48.),
            ('grip',eye_grip,aim_grip,50.),
        ):
            try:
                arr=self._p105_render(eye,aim,fov)
                im=Image.fromarray(arr)
                d=ImageDraw.Draw(im)
                # Small photography tag, no occlusion of main 3D action.
                d.rectangle((0,0,960,29),fill='#10283b')
                label=('P105 LIVE 3D FOLLOW CAMERA' if name=='follow' else 'P105 LIVE 3D GRIP CAMERA')
                d.text((12,7),label,fill='#ffffff')
                d.text((625,7),f'P104 physics | {self.count/self.fps:.2f}s',fill='#cde4ef')
                self._p105_writers[name].append_data(np.asarray(im))
                self._p105_frame_count[name]+=1
            except Exception as e:
                self._p105_errors.append({'frame':self.count,'camera':name,'error':repr(e)})
                # Diagnostic only; never change AI inference or physics control.

    def close(self):
        import json
        try:
            super().close()
        finally:
            for w in self._p105_writers.values():w.close()
            xs=[p['x'] for p in self._p105_xpoints if p['tracking']]
            report={
                'camera_only':True,'parent_p104':True,
                'real_pybullet_getCameraImage':True,
                'slider_link_tracked':'palm_camera_fixed',
                'follow_camera_position_uses_live_palm_x':True,
                'total_original_frames':self.count,
                'camera_frame_counts':self._p105_frame_count,
                'palm_x_min_max_m':[min(xs),max(xs)] if xs else None,
                'palm_x_motion_range_m':max(xs)-min(xs) if xs else None,
                'no_tracking_frames':self._p105_no_track,
                'errors':self._p105_errors,
                'sampled_palm_xyz':self._p105_xpoints[::max(1,len(self._p105_xpoints)//25)]
            }
            (self._p105_path/'p105_camera_audit.json').write_text(
                json.dumps(report,indent=2,ensure_ascii=False),'utf8')
# The imported Stage70 runner uses this recorder by its original import name.
Stage62Recorder=Stage105CameraOnlyRecorder
'''

def load_p104(work):
    p=work/'p104_reference_unchanged.py'
    p.write_bytes(P104_CODE)
    spec=importlib.util.spec_from_file_location('p104_reference_unchanged',p)
    mod=importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod

def launch(opts):
    p104bytes=hashlib.sha256(P104_CODE).hexdigest()
    work=Path(opts.work).resolve() if opts.work else Path(tempfile.mkdtemp(prefix='PAI105_'))
    work.mkdir(parents=True,exist_ok=True)
    if (work/'source').exists():raise SystemExit('STOP: WORKSPACE_NOT_NEW')
    p104=load_p104(work)
    raw, origin=p104.find_p92c(opts.p92c)
    source=p104.extract_verified(raw,work)
    before_orig=p104.tree_sha(source)
    stage104,diff104=p104.apply_stage104_state(source)
    after_p104=p104.tree_sha(source)
    ok,change=p104.check_against_pristine(before_orig,after_p104)
    assert ok, 'STOP: P104_BASELINE_UNEXPECTED_DIFFERENCES '+str(change)
    recorder=source/'stage88/stage62_workcell_video.py'
    original=recorder.read_bytes()
    assert original==recorder.read_bytes(), 'SOURCE_READ_ERROR'
    # No edits to the AI, robot dynamics, planner, training, 5-cameras, or runner.
    assert original.count(b'class Stage62Recorder:')==1
    assert b'Stage62Recorder=Stage105CameraOnlyRecorder' not in original
    recorder.write_bytes(original+CAMERA_APPEND.encode('utf8'))
    compile(recorder.read_bytes(),str(recorder),'exec')
    assert p104.sha_file(source/'stage88/run_stage70_continuous.py')==p104.RUNNER
    actual_changes={k for k,v in p104.tree_sha(source).items() if before_orig.get(k)!=v}
    assert actual_changes=={
        'stage88/stage84_camera_ai.py',
        'stage88/stage90_wound_evidence.py',
        'stage88/stage62_workcell_video.py',
        'stage88/stage58_apple_photo_assets/prepared/uv_photo_front/10_C1_uv.png',
    },'STOP: UNEXPECTED_SOURCE_CHANGE '+str(actual_changes)
    diff_rec=''.join(difflib.unified_diff(original.decode('utf8').splitlines(True),
      recorder.read_text('utf8').splitlines(True),fromfile='P104 presentation-only recorder',
      tofile='P105 camera-only appended recorder'))
    (work/'P105_RECORDER_ONLY.diff').write_text(diff_rec,encoding='utf8')
    (work/'P105_STAGE104_BASELINE.diff').write_text(diff104,encoding='utf8')
    hashes={
      'p92c':p104.P92C_SHA,
      'p104_script':p104bytes,
      'stage104_source':stage104,
      'original_recording_module':hashlib.sha256(original).hexdigest(),
      'p105_recording_module':p104.sha_file(recorder),
      'unmodified_physics_runner':p104.sha_file(source/'stage88/run_stage70_continuous.py'),
    }
    (work/'P105_SOURCE_AUDIT.json').write_text(json.dumps(hashes,ensure_ascii=False,indent=2),'utf8')
    print('P105_BASELINE_AND_CAMERA_ONLY_DIFF_PASS',work,flush=True)
    if opts.prepare_only:
        print('P105_PREPARE_ONLY_NO_PYBULLET',work,flush=True)
        return 0
    p104.preflight(source,work)
    hook=work/'pai103_hook';hook.mkdir()
    (hook/'sitecustomize.py').write_bytes(p104.HOOK_SOURCE)
    assert p104.sha_file(hook/'sitecustomize.py')==p104.HOOK_SHA
    cap=work/'pai105_ai_input_capture'
    original_code_sha={k:v for k,v in p104.tree_sha(source).items() if k.endswith('.py')}
    rc,result=p104.run_physics(source,work,hook,cap)
    phys=result/'stage70_physics'
    ai_ok,ai=p104.validate_capture(cap)
    grader=p104.grade_run(rc,result,cap)
    after_code_sha={k:v for k,v in p104.tree_sha(source).items() if k.endswith('.py')}
    same_python=(original_code_sha==after_code_sha)
    camera_file=phys/'p105_views/p105_camera_audit.json'
    camera=json.loads(camera_file.read_text('utf8')) if camera_file.is_file() else {'errors':['CAMERA_AUDIT_MISSING']}
    original_video=phys/'stage69_one_world_continuous_1x.mp4'
    view_videos=[phys/'p105_views'/('p105_'+name+'_live.mp4') for name in ('grip','slider_follow')]
    valid=bool(grader.get('all_10_verified') and same_python and camera.get('real_pybullet_getCameraImage')
       and not camera.get('errors') and camera.get('palm_x_motion_range_m',0)>.08
       and all(v.is_file() and v.stat().st_size>10000 for v in [original_video]+view_videos)
       and all(camera.get('camera_frame_counts',{}).get(n)==camera.get('total_original_frames') for n in ('grip','follow')))
    report={'time_jst':datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=9))).isoformat(),
      'stage':105,'purpose':'P104_SAME_PHYSICS_WITH_TWO_EXTRA_REAL_BULLET_OBSERVER_CAMERAS',
      'p104_parent_recorded_10of10':True,'rerun_physics_10of10':grader.get('all_10_verified'),
      'reproduction_claim':valid,'p104_grade_run':grader,'python_changed_during_run':not same_python,
      'ai_camera_capture_complete':ai_ok,'extra_cameras':camera,'physics_exit_code':rc,
      'source_hashes':hashes,
      'source_changes':['stage84 P99 restoration','stage90 P104 known candidate','C1 UV binding',
                        'stage62_workcell_video presentation-only 2-camera appended'],
      'original_success_files_unchanged':True,
      'videos':{v.name:{'size_bytes':v.stat().st_size,'sha256':p104.sha_file(v)}
                for v in [original_video]+view_videos if v.is_file()}}
    audit=work/'P105_CAPTURE_VERDICT.json'
    audit.write_text(json.dumps(report,ensure_ascii=False,indent=2,default=str),'utf8')
    output=work/'P105_CAMERA_VIEWS.zip'
    members=[audit,work/'P105_SOURCE_AUDIT.json',work/'P105_RECORDER_ONLY.diff',
             camera_file, original_video]+view_videos
    with zipfile.ZipFile(output,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=2) as z:
        for f in members:
            if f.is_file():z.write(f,f.name)
    with zipfile.ZipFile(output) as z:
        assert z.testzip() is None
    print('P105_VERDICT', 'PHYSICAL_10OF10_AND_CAMERAS_VERIFIED' if valid else 'NOT_VERIFIED',flush=True)
    print('P105_OUTPUT',output,output.stat().st_size,p104.sha_file(output),flush=True)
    # Work / Drive optional; no automatic user Drive write.
    return 0 if valid else 2

if __name__=='__main__':
    ap=argparse.ArgumentParser()
    ap.add_argument('--p92c')
    ap.add_argument('--work')
    ap.add_argument('--prepare-only',action='store_true')
    o=ap.parse_args()
    sys.exit(launch(o))
